'use client'

import { HttpLink } from '@apollo/client'
import { ApolloClient, ApolloNextAppProvider, InMemoryCache } from '@apollo/client-integration-nextjs'
import type { ReactElement, ReactNode } from 'react'

function makeClient(): ApolloClient {
  return new ApolloClient({
    cache: new InMemoryCache(),
    link: new HttpLink({ uri: '/api/graphql' }),
  })
}

export function InventoryApolloProvider({ children }: { children: ReactNode }): ReactElement {
  return <ApolloNextAppProvider makeClient={makeClient}>{children}</ApolloNextAppProvider>
}
import { CombinedGraphQLErrors } from '@apollo/client/errors'

export function errorMessage(error: unknown): string {
  if (CombinedGraphQLErrors.is(error)) return error.errors[0]?.message ?? error.message
  return error instanceof Error ? error.message : 'Something went wrong. Try again.'
}

export function label(value: string): string {
  const text = value.toLowerCase().replaceAll('_', ' ')
  return text ? text[0].toUpperCase() + text.slice(1) : ''
}

export function dateTime(value: string): string {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value))
}
'use client'

import { useState, type ReactElement } from 'react'
import { InventoryImport } from './inventory-import'
import { InventoryList } from './inventory-list'

export function InventoryWorkspace(): ReactElement {
  const [area, setArea] = useState<'frames' | 'imports'>('frames')
  const [jobId, setJobId] = useState('')

  return (
    <>
      <header className="masthead">
        <div className="masthead-content">
          <span className="product">Frame Inventory</span>
          <nav aria-label="Inventory navigation">
            <button
              aria-current={area === 'frames' ? 'page' : undefined}
              onClick={() => setArea('frames')}
            >
              Frames
            </button>
            <button
              aria-current={area === 'imports' ? 'page' : undefined}
              onClick={() => setArea('imports')}
            >
              Imports
            </button>
          </nav>
        </div>
      </header>
      <main>
        <section hidden={area !== 'frames'}>
          <div className="page-heading">
            <div>
              <h1>Frames</h1>
              <p className="subtle">Select a frame ID to view its version history.</p>
            </div>
            <button className="button button-primary" onClick={() => setArea('imports')}>
              Import CSV
            </button>
          </div>
          {area === 'frames' && (
            <InventoryList
              onJob={(id) => {
                setJobId(id)
                setArea('imports')
              }}
            />
          )}
        </section>
        <section hidden={area !== 'imports'}>
          <div className="page-heading">
            <div>
              <h1>Imports</h1>
              <p className="subtle">Upload inventory CSV files and review import results.</p>
            </div>
          </div>
          <InventoryImport trackedId={jobId} onTrack={setJobId} />
        </section>
      </main>
    </>
  )
}
query Frames($page: Int!, $statuses: [String!], $search: String) {
  frames(page: $page, size: 25, statuses: $statuses, search: $search) {
    page
    size
    hasNext
    items {
      frameId
      attributes {
        status
        environment
        siteNo
        address
        location {
          town
          postcode
        }
        format {
          technology
          formatCode
        }
      }
    }
  }
}

query FrameHistory($id: ID!) {
  frameHistory(frameId: $id) {
    versionId
    validFrom
    validTo
    current
    changeSource
    closedByChangeSource
    importJobId
    attributes {
      status
      statusReason
    }
  }
}
