'use client'

import { CombinedGraphQLErrors } from '@apollo/client/errors'
import { useQuery } from '@apollo/client/react'
import Link from 'next/link'
import { useState, type ReactElement, type ReactNode } from 'react'
import { FrameDetailDocument } from '../generated/graphql'
import { HistoryDialog } from './frame-history'
import { errorMessage } from './inventory-api'
import { StatusChip } from './inventory-list'

function DetailFields({ title, fields }: {
  title: string
  fields: ReadonlyArray<readonly [string, ReactNode]>
}): ReactElement {
  return (
    <section className="card detail-card">
      <h2>{title}</h2>
      <dl className="detail-fields">
        {fields.map(([name, value]) => (
          <div key={name}>
            <dt>{name}</dt>
            <dd>{value == null || value === '' ? <span className="subtle">—</span> : value}</dd>
          </div>
        ))}
      </dl>
    </section>
  )
}

export function FrameDetail({ frameId, onJob }: {
  frameId: string
  onJob: (jobId: string) => void
}): ReactElement {
  const [showHistory, setShowHistory] = useState(false)
  const { data, loading, error, refetch } = useQuery(FrameDetailDocument, {
    variables: { id: frameId },
    fetchPolicy: 'network-only',
    ssr: false,
  })
  const frame = data?.frame
  const notFound = data?.frame === null && !error || (
    CombinedGraphQLErrors.is(error) &&
    error.errors.every(({ extensions }) => extensions?.code === 'NOT_FOUND')
  )

  return (
    <>
      <Link className="text-button detail-back" href="/">← Back to frames</Link>
      <div className="page-heading detail-heading">
        <h1>{frameId}</h1>
        {frame && (
          <button className="button button-secondary" onClick={() => setShowHistory(true)}>
            Version history
          </button>
        )}
      </div>
      {loading ? (
        <p className="card panel-message" role="status">Loading frame details…</p>
      ) : notFound ? (
        <p className="card panel-message" role="status">Frame not found.</p>
      ) : error || !frame ? (
        <div className="card panel-message" role="alert">
          <p className="error">{error ? errorMessage(error) : 'Inventory service returned no result.'}</p>
          <button className="button button-secondary" onClick={() => {
            void refetch().catch(() => undefined)
          }}>
            Try again
          </button>
        </div>
      ) : (
        <div className="detail-grid">
          <DetailFields title="Frame" fields={[
            ['Status', <StatusChip value={frame.attributes.status} />],
            ['Status reason', frame.attributes.statusReason],
            ['Site number', frame.attributes.siteNo],
            ['Inventory site number', frame.attributes.inventorySiteNo],
            ['Panel number', frame.attributes.panelNumber],
            ['Location ID', frame.attributes.locationId],
            ['Environment', frame.attributes.environment],
          ]} />
          <DetailFields title="Location" fields={[
            ['Address', frame.attributes.address],
            ['Country code', frame.attributes.location?.countryCode],
            ['Region', frame.attributes.location?.region],
            ['Town', frame.attributes.location?.town],
            ['Postcode', frame.attributes.location?.postcode],
            ['Station', frame.attributes.station],
            ['Airport', frame.attributes.airport],
            ['Latitude', frame.attributes.latitude],
            ['Longitude', frame.attributes.longitude],
            ['Distance to closest school', frame.attributes.distanceToClosestSchool == null
              ? null : `${frame.attributes.distanceToClosestSchool} m`],
          ]} />
          <DetailFields title="Format and specifications" fields={[
            ['Technology', frame.attributes.format?.technology],
            ['Format code', frame.attributes.format?.formatCode],
            ['Size group code', frame.attributes.format?.sizeGroupCode],
            ['Size code', frame.attributes.sizeCode],
            ['Aspect ratio code', frame.attributes.aspectRatioCode],
            ['T-size', frame.attributes.tSize],
            ['Pixel height', frame.attributes.pixelHeight],
            ['Pixel width', frame.attributes.pixelWidth],
            ['Illumination type ID', frame.attributes.illuminationTypeId],
            ['Number of slots', frame.attributes.numberOfSlots],
          ]} />
          <DetailFields title="Commercial" fields={[
            ['Impact weight', frame.attributes.impactWeight],
            ['Premium', frame.attributes.premium ? 'Yes' : 'No'],
            ['Production rate card', frame.attributes.productionRateCard],
            ['Legacy production rate card', frame.attributes.productionRateCardLegacy],
            ['Pricing grade', frame.attributes.pricingGrade],
          ]} />
          {frame.externalReferences.length > 0 ? (
            <DetailFields title="External references" fields={
              frame.externalReferences.map(({ key, value }) => [key, value])
            } />
          ) : (
            <section className="card detail-card">
              <h2>External references</h2>
              <p className="subtle">No external references.</p>
            </section>
          )}
          <section className="card detail-card">
            <h2>Linked frames</h2>
            {frame.linkedFrameIds.length > 0 ? (
              <ul className="detail-links">
                {frame.linkedFrameIds.map((id, position) => (
                  <li key={`${position}:${id}`} className="mono">
                    {id === frameId ? id : (
                      <Link className="text-button" href={{ pathname: '/', query: { frameId: id } }}>
                        {id}
                      </Link>
                    )}
                  </li>
                ))}
              </ul>
            ) : <p className="subtle">No linked frames.</p>}
          </section>
        </div>
      )}
      {showHistory && (
        <HistoryDialog
          frameId={frameId}
          onClose={() => setShowHistory(false)}
          onJob={onJob}
        />
      )}
    </>
  )
}

